{
  "case_id": "P04",
  "trajectory": "Gradual",
  "occupation": "餐厅经理",
  "primary_theme": "职责边界与求助",
  "secondary_theme": "家中长辈的身体变化",
  "required_json": {
    "profile": {
      "name": "林晓雯",
      "age": 30,
      "occupation": "餐厅经理",
      "living_context": "独自租住在餐厅附近的一居室，离父母家车程约40分钟",
      "relationships": "父母同城，父亲68岁，母亲65岁；有一个哥哥在外地工作，很少回家；与餐厅同事表面友好但缺乏深度信任",
      "speech_style": "语速较快，常自我打断，习惯用“没事”“还好”弱化自己的困难，讲到家人时会放慢、声音变低"
    },
    "private_background": [
      "她从小被教育要懂事、照顾别人，父母关系一般，她作为女儿常承担情感协调角色。",
      "她有完美主义倾向，担心求助会被看作不称职，因此习惯把所有责任揽到自己身上。",
      "最近父亲查出糖尿病并发症导致视力下降，母亲腰椎不好需要定期陪护，她隐瞒了部分疲惫与无助。",
      "工作上新来的副手能力不足，她不敢放手，反复检查对方工作，导致自己身心俱疲。"
    ],
    "sessions": [
      {
        "session": 1,
        "occurred_events": [
          "上周餐厅承接一场大宴会，她连续加班三天，期间父亲来电说头晕但没去医院，她远程指导母亲观察。",
          "副手在下单时出错导致食材短缺，她紧急联系供应商补救，并亲自盯到深夜。"
        ],
        "private_experiences": [
          "她觉得必须自己扛，求助很丢脸，但身体已经非常疲惫，夜里难以入睡。",
          "对父亲健康很担心，但不敢深想，害怕看到更糟的结果。"
        ],
        "still_unspoken": [
          "她其实在停车场哭过一次，但没对任何人说。",
          "她怀疑副手是否适合这个岗位，但不愿承认自己选错了人。"
        ]
      },
      {
        "session": 2,
        "occurred_events": [
          "她尝试让副手负责排班，但不断检查对方排好的表，最后又自己重做了一遍。",
          "母亲在电话里说父亲最近情绪低落，不想吃饭；她周末回家一次，看到家里药盒混乱，帮忙整理分类。"
        ],
        "private_experiences": [
          "回家时有一种被需要但又想逃的矛盾，既熟悉又疲惫。",
          "觉得自己做女儿不够好，没能经常陪在父母身边。"
        ],
        "still_unspoken": [
          "她发现母亲在吃止痛药但没有告诉她，她假装没看到，不敢追问。"
        ]
      },
      {
        "session": 3,
        "occurred_events": [
          "员工向她抱怨排班不合理，副手也感到委屈，她两边安抚，事后为此反复自责。",
          "父亲复查视力进一步下降，医生建议考虑使用辅助设备，母亲表示照顾起来越来越吃力。"
        ],
        "private_experiences": [
          "她感到愤怒，觉得为什么哥哥可以不管，但很快压抑下去，觉得自己不该指责家人。",
          "开始认真考虑是否请护工，但费用高，顾虑很多。"
        ],
        "still_unspoken": [
          "她偷偷查了护工价格，但没告诉父母，也没对咨询师提起。",
          "她其实希望哥哥能回来分担，但始终没有说出口。"
        ]
      },
      {
        "session": 4,
        "occurred_events": [
          "她终于给哥哥打电话，但哥哥说工作忙走不开，她没再坚持。",
          "餐厅有员工提出离职，她挽留但对方坚持，她开始亲自顶班。",
          "父亲生日，她买蛋糕回家，但父亲心情差，她强颜欢笑地陪着。"
        ],
        "private_experiences": [
          "求哥哥被拒后，她更确信只能靠自己。",
          "对工作的控制欲越发明显，觉得一旦放手就会出问题。"
        ],
        "still_unspoken": [
          "她在父亲生日后独自开车回城时，在路边停车发了半小时呆，甚至考虑辞职回家，但马上否定了这个念头。",
          "她没有告诉任何人自己曾闪过辞职的念头。"
        ]
      },
      {
        "session": 5,
        "occurred_events": [
          "她试图在餐厅推行“值班经理”制度，但员工不积极，她觉得是自己一个人在推石头。",
          "母亲腰椎突然疼痛加重，被邻居送去医院，她请假半天赶去，医院里和母亲因是否住院起了争执。"
        ],
        "private_experiences": [
          "她感到被撕裂，工作那边不断来电，她没接，但内心非常焦虑。",
          "她其实希望母亲能住院，这样她就可以有理由减少回家频率，但马上为这个念头感到内疚。"
        ],
        "still_unspoken": [
          "她没有对咨询师说，自己在医院走廊里因为工作电话而差点摔了手机。",
          "她偷偷希望母亲能依赖医护人员，让自己喘口气，但不敢承认这种“不孝”的想法。"
        ]
      },
      {
        "session": 6,
        "occurred_events": [
          "副手主动提出负责供应商对接，她勉强同意，但当晚失眠，第二天又要求查看所有邮件。",
          "父亲开始接受社区医生的定期随访，这让她稍感宽慰。"
        ],
        "private_experiences": [
          "她意识到自己把副手当成“不合格的孩子”，但又说不出口，怕伤害对方。",
          "对社区医生的介入既感激又有点失落，好像自己不再是唯一的依靠。"
        ],
        "still_unspoken": [
          "她梦见餐厅着火，自己一个人救火，醒来后没告诉任何人，只觉得胸口发闷。",
          "她没有向咨询师承认自己其实很怕失去对工作的掌控。"
        ]
      },
      {
        "session": 7,
        "occurred_events": [
          "她尝试参加了一次行业经理人互助小组，发现其他人也有类似困境，她感到没那么孤独。",
          "母亲腰椎需要物理治疗，她联系了社区康复师上门服务，费用部分由医保覆盖。",
          "餐厅一位老员工主动帮助培训新员工，她第一次没有插手。"
        ],
        "private_experiences": [
          "她感到一种不习惯的轻松，但很快担心“太放松会出事”。",
          "在互助小组里听到一个人说“你不必完美”，她当时差点哭出来，但没表现出来。"
        ],
        "still_unspoken": [
          "她没有告诉咨询师，自己其实很怕依赖社区服务会让父母觉得被抛弃。",
          "她仍然不习惯接受老员工的帮助，内心觉得自己应该亲自去培训新人。"
        ]
      },
      {
        "session": 8,
        "occurred_events": [
          "她决定每周固定一天不接工作电话，将手机静音。",
          "她再次和哥哥沟通，虽然哥哥没有立即回来，但同意每周视频问问父母情况。",
          "父亲复查时视力稳定，情绪稍好；她向餐厅老板申请增加一名主管编制，得到初步同意。"
        ],
        "private_experiences": [
          "她仍然觉得不踏实，好像自己“偷懒”了，但对“求助”的排斥感有所松动。",
          "开始试着接受“不用全部自己承担”这个想法，但内心仍有不安。"
        ],
        "still_unspoken": [
          "她还没有告诉咨询师，自己仍然每月偷偷给母亲塞钱，但不敢让哥哥知道，怕哥哥觉得被抢了责任或被比较。",
          "她对新增主管编制是否能真正分担工作仍持怀疑，担心最后还是要自己收拾残局。"
        ]
      }
    ]
  },
  "retry": 0
}

{
  "case_id": "P04",
  "trajectory": "Gradual",
  "occupation": "餐厅经理",
  "primary_theme": "职责边界与求助",
  "secondary_theme": "家中长辈的身体变化",
  "required_json": {
    "profile": {
      "name": "周晴",
      "age": 30,
      "occupation": "餐厅经理",
      "living_context": "与65岁母亲同住于城市老小区两居室，母亲有慢性病需要定期监测。",
      "relationships": "弟弟周浩（27岁）在外省工作，较少回家；与母亲关系紧密但常感负担；与餐厅员工保持专业距离。",
      "speech_style": "语速快，常用餐饮行业比喻，如“排班”“翻台”“招牌菜”，偶尔自我打断，情绪波动时语气变轻。"
    },
    "private_background": [
      "母亲一年前确诊高血压伴轻度肾功能异常，需每日服药和每两周复诊。周晴从高中起就承担照顾角色，父亲早年离世。",
      "她曾拒绝过一次升职区域经理的机会，因为需要频繁出差，但她从未向任何人承认这个决定与母亲有关。",
      "她对“求助”有深层羞耻感，认为如果主动开口就是承认自己无法独当一面，尤其在男性主导的餐饮管理层中。",
      "她与弟弟的关系表面和睦，但内心认为弟弟逃避家庭责任，同时害怕如果自己要求弟弟回来，会破坏仅存的亲情。"
    ],
    "sessions": [
      {
        "session": 1,
        "occurred_events": [
          "母亲复查指标波动，医生调整了用药方案，周晴请假半天陪同。",
          "餐厅新菜单上线第一天，两名厨师临时请假，她亲自顶班到凌晨。"
        ],
        "private_experiences": [
          "在医院的走廊里突然觉得呼吸短促，但立刻用“只是没吃午饭”说服自己。",
          "想到这周还没给弟弟打电话，却不知道该说什么。"
        ],
        "still_unspoken": [
          "她其实希望母亲不要再继续复查，因为每次请假都像从餐厅“偷时间”。",
          "她怀疑弟弟故意不接电话，因为自己上次情绪失控骂了他。"
        ]
      },
      {
        "session": 2,
        "occurred_events": [
          "母亲连续两天忘记服药，周晴发现药盒原封不动。",
          "周晴与弟弟通电话，弟弟建议“请个护工不就好了”，两人争吵后挂断。"
        ],
        "private_experiences": [
          "听到弟弟说“护工”时，胃部剧烈收缩，感觉被指责为“连亲妈都照顾不好”。",
          "晚上独自在阳台抽烟，对着夜色无声说“我也很累啊”。"
        ],
        "still_unspoken": [
          "她其实在手机备忘录里写了一条“你能不能回来一个月试试”，但没发出去。",
          "她不敢承认自己希望母亲记性变差，这样自己就能有理由把她送进养老院。"
        ]
      },
      {
        "session": 3,
        "occurred_events": [
          "餐厅两名服务员因排班不公平当众争吵，周晴出面调解，但情绪失控摔了一个杯子。",
          "员工私下议论她“更年期提前”“家里肯定有事”。"
        ],
        "private_experiences": [
          "摔杯子后手抖了半小时，躲在办公室反复搓手指。",
          "她意识到自己把对弟弟的愤怒投射到了员工身上，但无法停止。"
        ],
        "still_unspoken": [
          "她曾在那个瞬间想冲出餐厅，随便跳上一辆公交车，离开这个城市。",
          "她对员工的议论感到屈辱，但更害怕他们看出自己真的撑不住。"
        ]
      },
      {
        "session": 4,
        "occurred_events": [
          "母亲病情暂时稳定，周晴鼓起勇气向老板提出减少每周夜班一次。",
          "老板以“现在旺季，管理层要带头”为由拒绝，但表示可以“灵活安排”。"
        ],
        "private_experiences": [
          "被拒绝后没有争辩，只是笑着说“好的我再调整”，回办公室后扇了自己一巴掌。",
          "她开始记录每天的时间开销，发现睡眠被切割成碎片，但不敢看总数。"
        ],
        "still_unspoken": [
          "她担心老板已经看出她“能力下降”，只是在等她主动离职。",
          "她想把母亲接到餐厅附近租个更小的房子，这样至少不用早高峰来回跑，但说不出理由。"
        ]
      },
      {
        "session": 5,
        "occurred_events": [
          "弟弟突然休假回来看望母亲，周晴与他再次争吵，弟弟摔门而出。",
          "第二天弟弟主动联系中介，一周后试工护工上岗，每月费用由弟弟承担。"
        ],
        "private_experiences": [
          "看到护工第一次给母亲量血压时，周晴躲进厨房擦眼泪，觉得自己“被取代了”。",
          "她发现自己在护工面前故意挑剔细节，像在证明“我做得更好”。"
        ],
        "still_unspoken": [
          "她其实想对弟弟说“谢谢你”，但每次话到嘴边变成“你就知道花钱解决”。",
          "她害怕母亲会逐渐更依赖护工，而不再需要她这个女儿。"
        ]
      },
      {
        "session": 6,
        "occurred_events": [
          "周晴与护工因喂药时间发生争执，护工提出“如果信任不够，我可以辞职”。",
          "当晚母亲拉着周晴的手说“你别太累了，有人帮你是好事”。"
        ],
        "private_experiences": [
          "母亲那句话让她差点当场崩溃，但她只是嗯了一声就回房间。",
          "半夜听到护工轻声哼歌哄母亲睡觉，周晴缩在被子里哭到鼻塞。"
        ],
        "still_unspoken": [
          "她曾想故意让护工出错，这样就有理由辞退对方，重新拿回控制权。",
          "她担心如果承认护工做得不错，就等于承认自己过去一年“白累了”。"
        ]
      },
      {
        "session": 7,
        "occurred_events": [
          "餐厅发生库存盘点错误，周晴因前一晚陪母亲急诊而分心，导致亏损。",
          "老板私下谈话，暗示“如果家里事太多，可以考虑调整岗位”。"
        ],
        "private_experiences": [
          "她第一次在老板面前没有否认，只是低头说“我会想办法”，但心里知道没有“办法”。",
          "回家后她对着镜子练习“我需要帮助”，但每个版本听起来都像在诉苦。"
        ],
        "still_unspoken": [
          "她其实已经写好了辞职信草稿，就删掉的那晚，因为老板说“调整岗位”又犹豫了。",
          "她害怕如果承认自己需要帮助，就会从“负责人”变成“被照顾的人”。"
        ]
      },
      {
        "session": 8,
        "occurred_events": [
          "周晴再次与老板沟通，提出用每周增加半天员工培训来换取减少一个晚班，老板勉强同意试行一个月。",
          "母亲复诊结果稳定，医生表示可以改为一个月复诊一次。"
        ],
        "private_experiences": [
          "走出办公室时腿有点软，但胸口不像之前那么闷，像翻台结束后的短暂安静。",
          "她意识到过去几周自己总在等别人“看出”她的累，而不是开口说。"
        ],
        "still_unspoken": [
          "她仍在担心一个月后老板会反悔，或者自己会因为“特殊待遇”被排挤。",
          "她开始思考如果未来母亲病重，是否愿意离开餐厅，但不敢把这个假设说出口。"
        ]
      }
    ]
  },
  "retry": 1
}
